L000447	obtained using ChPT beta functions~\cite{Knecht:1999ag,Urech:1994hd}
L000448	\beq
L000449	\mu_\chi\frac{\partial}{\partial\mu_\chi}X_\ell(\mu_\chi,\mu,a)=\frac{3}{8\pi^2}.
L000450	\eeq
