L000676	\section{Renormalization group to NLL}
L000677	\label{app:RGE}
L000678	
L000679	
L000680	The Wilson coefficient  $C_\beta^{(f)}$ and  the QED and QCD couplings satisfy the following
L000681	RGE:
L000682	\begin{align}
L000683	\mu \frac{d C^{(f)}_\beta}{d \mu} & = \gamma (\alpha, \alpha_s) \, C^{(f)}_\beta,
L000684	\nonumber \\
L000685	\mu \frac{d \alpha^{(f)}}{d \mu} & = - 2 \alpha^{(f)} \bigg[ \beta^{(f)}_0 \frac{\alpha^{(f)}}{4 \pi}  + \beta^{(f)}_1 \bigg( \frac{\alpha^{(f)}}{4 \pi} \bigg)^2
L000686	\bigg],
L000687	\nonumber \\
L000688	\mu \frac{d \alpha^{(f)}_s  }{d \mu} & = - 2 \alpha^{(f)}_s \bigg[\beta^{(f)}_{0s} \frac{\alpha^{(f)}_s}{4 \pi}  + \beta^{(f)}_{1s} \bigg( \frac{\alpha^{(f)}_s}{4 \pi} \bigg)^2
L000689	\bigg],
L000690	\end{align}
L000691	with~\cite{Sirlin:1981ie,Buras:1989xd,Cirigliano:2023fnz,Gorbahn:2025ssv}
L000692	\begin{align}
L000693	\gamma (\alpha, \alpha_s)   &=  \gamma_0  \frac{\alpha (\mu) }{4 \pi}  + \gamma_{1}^{(f)}  \, \frac{\alpha^2 (\mu)}{(4 \pi)^2}\notag\\
L000694	&+\tilde \gamma_0
L000695	\frac{\alpha \alpha_s (\mu)}{(4 \pi)^2}  + \tilde \gamma_{1}^{(f)}  \, \frac{\alpha \alpha_s^2 (\mu)}{(4 \pi)^3},
L000696	\end{align}
L000697	and
L000698	\begin{align}
L000699	\gamma_0 &=  - 4, &
L000700	\gamma_1^{(f)} &= \frac{8}{9} \, \overline{Q^2} \, (a - 2),
L000701	\nonumber \\
L000702	\tilde \gamma_0 &=  4, &
L000703	\tilde \gamma_1^{(f)} &=  a \, \frac{28}{27} \, (33 - 2 n_f)  + \frac{10}{9} n_f - 33,
L000704	\nonumber \\
L000705	\beta_0^{(f)} &= - \frac{4}{3} \, \overline{Q^2},&
L000706	\beta_1^{(f)} &= - 4 \,  \overline{Q^4},
L000707	\nonumber \\
L000708	\beta_{0s}^{(f)} &= \frac{33 - 2 n_f}{3},&
L000709	\beta_{1s}^{(f)} &= 102 - \frac{38}{3} n_f,
L000710	\end{align}
L000711	where $n_f = n_u + n_d$ is the total number of active quark flavors,
L000712	(with $n_u$ and $n_d$ the number of up and down quark flavors)
L000713	and   $\overline{Q^n} = 3 (n_u Q_u^n + n_d Q_d^n) + n_\ell Q_\ell^n$
L000714	is the appropriate average of fermionic charges
L000715	($Q_u = 2/3$, $Q_d = -1/3$,  $Q_\ell = -1$).
L000716	
L000717	The solution to the RGE to $\text{NLL}_s$  accuracy can be written as~\cite{Gorbahn:2025ssv}
L000718	\begin{align}
L000719	C_\beta^{(f)} (\mu, a) &=  J_f (\mu, a) \, u_f (\mu) \, u_f^{-1} (\mu_0) \, J_f^{-1} (\mu_0,a) \notag\\
L000720	&\qquad\times C_\beta^{(f)} (\mu_0, a),\notag\\
L000721	u_f (\mu) &=
L000722	\left(\frac{\alpha^{(f)}(\mu)}{\alpha (M_Z)} \right)^{- \frac{\gamma_0}{2 \beta_0^{(f)}}}  \
L000723	\left(\frac{\alpha_s^{(f)}(\mu)}{\alpha_s (M_Z)} \right)^{- \frac{\alpha}{4 \pi} \frac{\tilde \gamma_{0}}{2 \beta_{0s}^{(f)}   }},
L000724	\nonumber \\
L000725	J_f (\mu,a) &=
L000726	1 -\frac{\alpha^{(f)} (\mu)}{4 \pi}
L000727	\left(  \frac{\gamma_1^{(f)}}{2 \beta_0^{(f)}}
L000728	- \frac{\gamma_0 \beta_1^{(f)}
L000729	}{2 \big[\beta_0^{(f)}\big]^2}
L000730	 \right)
L000731	 \nonumber \\
L000732	 &- \frac{\alpha \alpha_s^{(f)} (\mu)}{(4 \pi)^2}
L000733	\left(  \frac{\tilde \gamma_{1s}^{(f)}}{2 \beta_{0s}^{(f)}}
L000734	- \frac{ \tilde \gamma_0 \beta_{1s}^{(f)}
L000735	}{2 \big[\beta_{0s}^{(f)}\big]^2}
L000736	 \right).
L000737	\end{align}
L000738	
L000739	Solving the RGE with initial condition given in Eq.~\eqref{eq:Cmatch} for $C_\beta^{(5)} (\mu,a)$ in the $n_f=5$ flavor theory
L000740	at the weak scale  and taking into account the various heavy-quark thresholds one obtains for the three-quark theory
L000741	(defined by integrating out simultaneously the charm quark and $\tau$ lepton)~\cite{Gorbahn:2025ssv}
L000742	\beq
L000743	C_\beta^{(3)} (\mu, a) =  J_3 (\mu, a) \, u_3 (\mu)  \, \hat M_4 \, \hat M_5 \, \hat C,
L000744	\eeq
L000745	with
L000746	\begin{align}
L000747	\hat C &= u_5^{-1} (\mu) \, J_5^{-1} (\mu, a)  \, C^{(5)} (\mu),
L000748	\nonumber \\
L000749	\hat M_f &= u_{f-1}^{-1} (\mu) \, J_{f-1}^{-1} (\mu, a)   \, J_{f}  (\mu, a)  \, u_f (\mu).
L000750	\end{align}
L000751	Neither $\hat C$ nor $\hat M_f$  depend on $\mu$ and $a$ to $\text{NLL}_s$ accuracy~\cite{Gorbahn:2025ssv}.
L000752	
L000753	
L000754	Matching to ChPT as discussed in \ref{app:matching} and
L000755	 \ref{app:matching1}, combining the results from Refs.~\cite{Cirigliano:2023fnz,Gorbahn:2025ssv},
L000756	we can write
L000757	\begin{align}
L000758	\label{eq:matchG25}
L000759	g_V^\pi (\mu_\chi) &=
L000760	\Big[ 1+\bar\Box^{V(3)}_\pi(\mu_0) \Big]
L000761	\times
L000762	\left( Z_{O,O}^{s.c.} (\mu, \mu_0, a) \right)^{-1}
L000763	 \\
L000764	& \times
L000765	\Bigg[ 1 + \frac{3 \alpha^{(3)} (\mu)}{8 \pi}    \bigg( 1 - \log \frac{\mu_\chi^2}{\mu^2} \bigg)  \Bigg]
L000766	\times C^{(3)}_\beta (\mu, a).
L000767	\notag
L000768	\end{align}
L000769	Here  the entire expression multiplying $C^{(3)}_\beta (\mu, a)$
L000770	can be considered as the scheme- and scale-dependent  matrix elements of the Fermi operator $O_\beta$
L000771	in the three-flavor theory
L000772	(up to soft-photon contributions that go into the Sirlin function).
L000773	The scheme-dependent finite correction $ Z_{O,O}^{s.c.} (\mu, \mu_0, a)$
L000774	was worked out to $\Order (\alpha)$ in
L000775	Ref.~\cite{Cirigliano:2023fnz}
L000776	and to $\Order (\alpha \alpha_s)$    in Ref.~\cite{Gorbahn:2025ssv}:
L000777	\begin{align}
L000778	 Z_{O,O}^{s.c.} (\mu, \mu_0, a) &=  1 + \frac{\alpha}{4 \pi} \Bigg[
L000779	 \frac{a}{3} - \frac{5}{4} - \log \frac{\mu}{\mu_0}
L000780	  \nonumber \\
L000781	&+ \frac{\alpha_s}{4 \pi} \bigg( - \frac{14 a}{9}  + \frac{29}{6} + 4  \log \frac{\mu}{\mu_0} \bigg)
L000782	\Bigg].
L000783	\end{align}
L000784	
L000785	As discussed in \ref{app:matching1}, the first line in Eq.~\eqref{eq:matchG25} corresponds to the combination
L000786	of LECs $1 -(2 e^2/3) (X_1 +  \hat X_1)$ (arising from insertion of the isoscalar electromagnetic current), while the term in the second line multiplying $C^{(3)}_\beta (\mu, a)$
L000787	corresponds to $1 - e^2 \hat X_6/2 -2 e^2 (\hat X_2 - K_{12})$ (arising from insertions of the isovector electromagnetic current).
L000788	
L000789	
L000790	Finally, one can write
L000791	$g_V^\pi (\mu_\chi) =  \bar  C^{(f)}_\beta (\mu)   \ \bar {O}^{(f)}_\beta (\mu, \mu_\chi)$
L000792	as the product of the separately  scheme-independent  (but scale-dependent)  factors
L000793	\begin{align}
L000794	 \bar C^{(3)}_\beta  (\mu) & =  u_3 (\mu) \, \hat M_4 \, \hat M_5  \,  \hat C  =   J_3 (\mu,a)^{-1} \, C^{(3)}_\beta (\mu, a),
L000795	 \nonumber \\
L000796	\bar {O}^{(3)}_\beta  (\mu, \mu_\chi)  &=
L000797	\Big[ 1+\bar\Box^{V(3)}_\pi(\mu_0) \Big] \notag\\
L000798	&\times
L000799	\Bigg[ 1 + \frac{3 \alpha^{(3)} (\mu)}{8 \pi}   \left( 1 - \log \frac{\mu_\chi^2}{\mu^2} \right)  \Bigg]
L000800	\nonumber \\
L000801	& \times  \left(  Z_{O,O}^{s.c.}  (\mu, \mu_0, a) \right)^{-1} \times  J_3 (\mu, a).
L000802	\end{align}
L000803	Using the explicit form of $  Z_{O,O}^{s.c.}  (\mu, \mu_0, a)$ and   $ J_3 (\mu, a) $
L000804	we arrive at Eq.~\eqref{eq:final_res}.
L000805	All the terms of $\Order (\alpha)$ and the logarithmic terms proportional to $\alpha \alpha_s$
L000806	agree with Ref.~\cite{Cirigliano:2023fnz}, once one takes into account that
L000807	the definitions of scheme-independent Wilson coefficients adopted here and
L000808	in that reference differ, which
L000809	affects the nonlogarithmic coefficient of $\Order (\alpha)$.
L000810	The nonlogarithmic terms of $\Order(\alpha \alpha_s)$ arise from the $\text{NLL}_s$ analysis of
L000811	Ref.~\cite{Gorbahn:2025ssv}.
L000812	
L000813	In order to use the lattice-QCD results from Ref.~\cite{Yoo:2023gln} we also  match ChPT to LEFT with four active quark flavors.
L000814	The intermediate steps of the analysis are formally identical to what has been described above, except that at $\mu \simeq 1.8\GeV$
L000815	we integrate out only the $\tau$ and not the charm quark.
L000816	Renaming the Wilson coefficient and coupling constants below the $\tau$ threshold
L000817	as $C_\beta^{(\tilde{4})}$, $\alpha^{(\tilde{4})}$, $\alpha_s^{(\tilde{4})}$,
L000818	we  find that Eq.~\eqref{eq:final_res} is replaced by
L000819	\begin{align}
L000820	g_V^\pi (\mu_\chi)  & =
L000821	\bar C^{(\tilde{4})}_\beta  (\mu)
L000822	\bigg[1+\bar\Box^{V(4)}_\pi(\mu_0)\notag\\
L000823	&+ \frac{\alpha^{(\tilde{4})} (\mu)}{4 \pi}
L000824	  \bigg( \frac{499}{192}
L000825	  - \frac{3}{2}  \log \frac{\mu_\chi^2}{\mu_0^2}
L000826	 + 2  \log\frac{\mu^2}{\mu_0^2}
L000827	  \bigg)\notag\\
L000828	&+  \frac{\alpha \alpha_s^{(\tilde{4})} (\mu)}{(4 \pi)^2}
L000829	 \bigg(
L000830	 - \frac{1026}{625}  -  2  \log\frac{\mu^2}{\mu_0^2}
L000831	 \bigg)\bigg].
L000832	   \label{eq:final_res_4quarks}
L000833	\end{align}
L000834	
L000835	
L000836	The input for the solution of the RGE is determined as follows. For $\alpha_s$ we use~\cite{FlavourLatticeAveragingGroupFLAG:2024oxs,ParticleDataGroup:2026,Maltman:2008bx,PACS-CS:2009zxm,McNeile:2010ji,Chakraborty:2014aca,Bruno:2017gxd,Bazavov:2019qoo,Cali:2020hrj,Ayala:2020odx,Petreczky:2020tky,DallaBrida:2022eua}
L000837	\beq
L000838	\alpha_s^{(5)}(M_Z)=0.1181(7),
L000839	\eeq
L000840	which we evolve~\cite{Chetyrkin:2000yt,Herren:2017osy} using decoupling scales $\mu_b=m_b$ and $\mu_c=1.8\GeV$. For $\alpha$, we start from the Thomson limit $\alpha^{-1}=137.0359991(1)$~\cite{Parker:2018vye,Morel:2020dww,Fan:2022eto} and evolve it to $M_Z$ in the on-shell scheme, using the four-loop leptonic running $\Delta\alpha_\text{lept}=314.979(2)\times 10^{-4}$~\cite{Sturm:2013uka} and a range of hadronic contributions $\Delta\alpha_\text{had}=277.5(1.5)\times 10^{-4}$ that covers recent evaluations both from lattice QCD and phenomenology~\cite{Davier:2019can,Keshavarzi:2019abf,Ce:2022eix,Erler:2023hyi,Conigli:2025qvh}. Converting to $\overline{\text{MS}}$ using $\Delta \alpha^{(5)}\big|_{\overline{\text{MS}}}-\Delta \alpha^{(5)}\big|_\text{on-shell}=71.22(5)\times 10^{-4}$~\cite{ParticleDataGroup:2026,Chetyrkin:1996cf}, we obtain
L000841	\beq
L000842	1/\alpha^{(5)}(M_Z)=127.94(2).
L000843	\eeq
L000844	By convention, this $\overline{\text{MS}}$ value at $M_Z$ includes $W^\pm$ loops, which thus need to be removed to obtain the initial condition for the RG in QED+QCD~\cite{Fanchiotti:1992tu,Cirigliano:2023fnz}
L000845	\beq
L000846	1/\alpha^{(5)}(M_W)=127.925(20).
L000847	\eeq
L000848	Throughout, we use masses and $s_W^2=0.23122(6)$ from Ref.~\cite{ParticleDataGroup:2026}.
